#ifndef WOLLITZ3_PES6_MATCH_VIEWS_H
#define WOLLITZ3_PES6_MATCH_VIEWS_H

#include <stddef.h>

/* PC layouts corroborated by Subarasheese/pes6decomp, revision
 * 6c3035b3e36ec844d0c8232df655c3638a26d364, include/pes6/match_player.h
 * and docs/ball_physics.md. See research/pes6decomp/crosswalk.json.
 * Names are descriptive; no original debug symbols are claimed.
 * Unknown bytes remain explicit. These are PC views, not a shared PS2 ABI.
 */
struct Pes6PcMatchPlayer {
    unsigned char unknown00[0x11];
    unsigned char squad_slot;       /* +0x11 */
    unsigned char squad;            /* +0x12 */
    unsigned char side;             /* +0x13 */
    short goal_direction;           /* +0x14; observed +1/-1 */
    unsigned char role;             /* +0x16 */
    unsigned char unknown17[5];
    int speed;                     /* +0x1c */
    unsigned char unknown20[10];
    unsigned short angle_2a;       /* +0x2a; added to ball direction by 00a2c7f0 */
    unsigned char unknown2c[0x240 - 0x2c];
};

/* Prefix only: the original ball has more fields beyond this view. */
struct Pes6PcBallMotion {
    unsigned char unknown00[0x10];
    float position[3];             /* +0x10; negative Y points up */
    unsigned char unknown1c[4];
    float previous_position[3];    /* +0x20 */
    unsigned char unknown2c[4];
    float vertical_velocity;       /* +0x30 */
    unsigned char unknown34[0x1c];
    int horizontal_speed;          /* +0x50 */
    unsigned char unknown54[4];
    unsigned short direction;      /* +0x58; 65536 is one turn */
    unsigned short previous_direction;
    unsigned char unknown5c[6];
    unsigned char state;           /* +0x62 */
    unsigned char previous_state;
    unsigned char unknown64[6];
    unsigned short curl_counter;   /* +0x6a */
    unsigned char curl_direction;   /* +0x6c */
    unsigned char unknown6d[7];
    int spin;                      /* +0x74 */
};

/* Supported by both MSVC 7.1 and Clang; fail compilation if a view drifts. */
typedef char Pes6PlayerStride[(sizeof(Pes6PcMatchPlayer) == 0x240) ? 1 : -1];
typedef char Pes6PlayerSquadOffset[(offsetof(Pes6PcMatchPlayer, squad) == 0x12) ? 1 : -1];
typedef char Pes6PlayerSideOffset[(offsetof(Pes6PcMatchPlayer, side) == 0x13) ? 1 : -1];
typedef char Pes6PlayerDirectionOffset[(offsetof(Pes6PcMatchPlayer, goal_direction) == 0x14) ? 1 : -1];
typedef char Pes6PlayerSpeedOffset[(offsetof(Pes6PcMatchPlayer, speed) == 0x1c) ? 1 : -1];
typedef char Pes6PlayerAngleOffset[(offsetof(Pes6PcMatchPlayer, angle_2a) == 0x2a) ? 1 : -1];
typedef char Pes6BallPositionOffset[(offsetof(Pes6PcBallMotion, position) == 0x10) ? 1 : -1];
typedef char Pes6BallVelocityOffset[(offsetof(Pes6PcBallMotion, vertical_velocity) == 0x30) ? 1 : -1];
typedef char Pes6BallSpeedOffset[(offsetof(Pes6PcBallMotion, horizontal_speed) == 0x50) ? 1 : -1];
typedef char Pes6BallDirectionOffset[(offsetof(Pes6PcBallMotion, direction) == 0x58) ? 1 : -1];
typedef char Pes6BallStateOffset[(offsetof(Pes6PcBallMotion, state) == 0x62) ? 1 : -1];
typedef char Pes6BallCurlOffset[(offsetof(Pes6PcBallMotion, curl_counter) == 0x6a) ? 1 : -1];
typedef char Pes6BallCurlDirectionOffset[(offsetof(Pes6PcBallMotion, curl_direction) == 0x6c) ? 1 : -1];
typedef char Pes6BallSpinOffset[(offsetof(Pes6PcBallMotion, spin) == 0x74) ? 1 : -1];

#endif

